{
  "arguments": [
    {
      "claim": "The killings, cruel treatment and destruction of homes in Ljuboten constitute war crimes under the Rome Statute.",
      "reasoning": "Article 8 of the Rome Statute enumerates grave breaches that are war crimes, including wilful killing, torture or inhuman treatment, and extensive destruction of property not justified by military necessity. The factual record shows that unarmed civilians were shot dead, subjected to beatings and threats, and that dozens of houses were set alight without any demonstrated military objective. These acts therefore fall within the categories listed in Art. 8(a)(i), 8(a)(ii) and 8(a)(iv), as well as the common Article 3 violation of violence to life and cruel treatment (Art. 8(c)(i)).",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Wilful killing;"
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Torture or inhuman treatment, including biological experiments;"
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Extensive destruction and appropriation of property, not justified by military necessity and carried out unlawfully and wantonly;"
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Violence to life and person, in particular murder of all kinds, mutilation, cruel treatment and torture;"
        }
      ]
    },
    {
      "claim": "An internationalised internal armed conflict existed in Macedonia at the time, so the provisions of Article 8(c) and the common Article 3 of the Geneva Conventions apply.",
      "reasoning": "Article 8(c) applies to armed conflicts not of an international character that are “protracted armed conflict between governmental authorities and organized armed groups”. The presence of the National Liberation Army, the large‑scale police and army operation, and the systematic attacks on the civilian population demonstrate a protracted conflict rather than a mere disturbance. Consequently, the serious violations listed in Art. 8(c) are applicable, and the acts in Ljuboten are punishable as war crimes.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "For the purpose of this Statute, \"war crimes\" means:"
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "8",
          "quoted_text": "Paragraph 2 (c) applies to armed conflicts not of an international character and thus does not apply to situations of internal disturbances and tensions, such as riots, isolated and sporadic acts of violence or other acts of a similar nature."
        }
      ]
    },
    {
      "claim": "Johan Tarčulovski is individually criminally responsible for the war crimes committed in Ljuboten, both as a direct perpetrator and under command responsibility.",
      "reasoning": "Customary international law imposes individual criminal responsibility for war crimes (Rule 151) and holds commanders and superiors liable for crimes committed by forces under their effective control (Rule 152). Tarčulovski commanded the reserve police, was present during the attacks, and ordered or permitted the unlawful use of force. Under Article 33(1) of the Rome Statute, the defence of acting on superior orders does not relieve him of responsibility. Therefore, he can be held liable for the killings, torture, and property destruction.",
      "citations": [
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 151,
          "quoted_text": "Individuals are criminally responsible for war crimes they commit."
        },
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 152,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed pursuant to their orders."
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "33(1)",
          "quoted_text": "The fact that a crime within the jurisdiction of the Court has been committed by a person pursuant to an order of a Government or of a superior, whether military or civilian, shall not relieve that person of criminal responsibility unless:"
        }
      ]
    },
    {
      "claim": "The claim that the operation was a lawful law‑enforcement action or a defensive operation does not excuse criminal responsibility under international humanitarian law.",
      "reasoning": "Article 31(1)(c) of the Rome Statute expressly states that participation in a defensive operation does not itself constitute a ground for excluding criminal responsibility. Moreover, the police units involved were civilian law‑enforcement personnel equipped only with light weapons for order‑keeping (Art. I § 67(1)(d)), which under Article I § 65(3) are to be respected as civilians and not treated as combatants. The indiscriminate attacks on civilians and civilian property therefore cannot be justified as a legitimate security or defensive measure.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "31(1)(c)",
          "quoted_text": "The fact that the person was involved in a defensive operation conducted by forces shall not in itself constitute a ground for excluding criminal responsibility under this subparagraph;"
        },
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "67(1)(d)",
          "quoted_text": "such personnel and such units are equipped only with light individual weapons for the purpose of maintaining order or for self-defence. The provisions of Article 65, paragraph 3 shall also apply in this case;"
        },
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "65(3)",
          "quoted_text": "It shall also not be considered as an act harmful to the enemy that civilian civil defence personnel bear light individual weapons for the purpose of maintaining order of for self-defence. However, in areas where land fighting is taking place or is likely to take place, the Parties to the conflict shall undertake the appropriate measures to limit these weapons to handguns, such as pistols or revolvers, in order to assist in distinguishing between civil defence personnel and combatants. Although civil defence personnel bear other light individual weapons in such areas, they shall nevertheless be respected and protected as soon as they have been recognized as such."
        }
      ]
    }
  ]
}

